// src/Components/VectorMap.jsx
import { useRef, useEffect } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

export default function VectorMap({ center = [79.109468, 21.096398], zoom = 18, apiKey }) {
  const mapRef = useRef(null);

  useEffect(() => {
    if (!mapRef.current) return;
    // const key = apiKey || (import.meta?.env?.VITE_MAPTILER_KEY) || process.env.REACT_APP_MAPTILER_KEY || "at5jM9LfyXwAvnCaHKoI	";
    const styleUrl = `https://api.maptiler.com/maps/streets-v2/style.json?key=at5jM9LfyXwAvnCaHKoI	`;

    const map = new maplibregl.Map({
      container: mapRef.current,
      style: styleUrl,
      center,
      zoom,
      maxZoom: 23,
    });

    // optional simple marker so you see a point
    const marker = new maplibregl.Marker().setLngLat(center).addTo(map);

    return () => {
      marker.remove();
      map.remove();
    };
  }, [center, zoom, apiKey]);

  return <div ref={mapRef} style={{ width: "100%", height: "100%" }} />;
}
